// Prints the story -> model -> paths listing, including the routes no path reaches.
import { queryParameters, routeInventory } from "../apps/web/browser/stories/route-inventory";
import { stories } from "../apps/web/browser/stories/stories";
import { generatePaths } from "../apps/web/browser/stories/story-graph";

export function coverageListing() {
  const lines = [
    "# Story test coverage",
    "",
    "Generated by `bun run stories:coverage > docs/specs/story-coverage.md`; a test keeps it current. See [story-e2e.md](story-e2e.md). Coverage describes the declared models, not every possible behavior (Decision Atlas 6.2).",
    "",
    "| Story | Model states | PR paths | Full paths | Sources |",
    "| --- | ---: | ---: | ---: | --- |",
  ];
  for (const story of stories) {
    const pr = generatePaths(story.model, story.events, "pr");
    const full = generatePaths(story.model, story.events, "full");
    lines.push(
      `| ${story.id} | ${Object.keys(story.model.states).length} | ${pr.length} | ${full.length} | ${story.sources.join("; ")} |`,
    );
  }
  for (const story of stories) {
    lines.push("", `## ${story.id}: ${story.title}`, "");
    for (const path of generatePaths(story.model, story.events, "pr")) {
      lines.push(`- ${path.name}`);
    }
  }
  lines.push("", "## Route inventory", "", "| URL | View | Reached by |", "| --- | --- | --- |");
  for (const route of routeInventory) {
    const url = route.url.replaceAll("|", "\\|");
    lines.push(
      `| \`${url}\` | ${route.view} | ${route.state ?? `NOT REACHED: ${route.notCovered}`} |`,
    );
  }
  lines.push("", "## Query parameters", "", "| Parameter | Coverage |", "| --- | --- |");
  for (const [name, coverage] of Object.entries(queryParameters)) {
    lines.push(`| \`${name}\` | ${coverage} |`);
  }
  return `${lines.join("\n")}\n`;
}

if (import.meta.main) {
  process.stdout.write(coverageListing());
}
